const {chromium}=require(process.env.PLAYWRIGHT_MODULE || 'playwright');const assert=require('assert/strict'),fs=require('fs');
const base=process.env.SAWTI_TEST_BASE||'http://127.0.0.1:3002';
const clean=s=>s.replace(/[\u064b-\u065f\u0670\u0640]/g,'');
async function click(p,t){for(let i=0;i<50;i++){for(const b of await p.getByRole('button').all())if(await b.isVisible()&&clean(await b.innerText()).includes(t)){await b.click();return}await p.waitForTimeout(100)}throw Error('missing '+t)}
(async()=>{const b=await chromium.launch({channel:'chrome',headless:true}),results=[];await Promise.all(['treasure-map','diver-pearl','balloon'].map(async game=>{const p=await b.newPage({viewport:{width:1440,height:1000}});await p.goto(base+'/writing-games/'+game);await p.getByRole('heading').first().waitFor();await p.locator('.game-stage-card > button').last().click();await p.locator('.game-map-hint').waitFor();for(const width of [390,768,1440]){await p.setViewportSize({width,height:900});for(const ms of [0,400,400]){await p.waitForTimeout(ms);const hint=await p.locator('.game-map-hint button').boundingBox(),node=await p.getByRole('button',{name:'متابعة المرحلة الحالية'}).boundingBox();assert(hint&&node);assert(hint.y>=node.y+node.height+1,game+' overlap');assert(hint.x>=0&&hint.x+hint.width<=width,game+' clipped');assert(hint.y+hint.height<=900,game+' bottom clipping');}await p.screenshot({path:'/private/tmp/sawti-map-'+game+'-'+width+'.png'});}await p.locator('.game-map-hint button').click();await p.locator('video').waitFor();await p.getByRole('button',{name:'العودة إلى المهام'}).click();await p.waitForURL('**/writing-games');results.push({game,status:'PASS',checks:'no overlap/clipping at 390/768/1440 through animation; hint opens video; back returns to tasks'});await p.close()}));fs.writeFileSync('/private/tmp/sawti-map-layout-results.json',JSON.stringify(results,null,2));console.log(results);await b.close()})();
